text:
/* 暗色科幻风 — 修改 CSS 变量快速换肤 */
.xt-root {
    --xt-bg: #0e1117;
    --xt-text: #e0e0e0;
    --xt-text-sub: #8888aa;
    --xt-text-muted: #555577;
    --xt-accent: #63b3ed;
    --xt-accent-bg: rgba(99,179,237,0.1);
    --xt-border: #2a2a44;
    --xt-radius: 20px;
    --xt-font: "Kaiti", "STKaiti", serif;
}
.xt-avatar { border-color: var(--xt-accent); }
.xt-section-body { border-left-width: 4px; font-size: 17px; }
.xt-grid-stat { background: rgba(255,255,255,0.04); }
.xt-bar-fill { background: linear-gradient(to right, #63b3ed, #b794f4); }
.xt-bubble-right .xt-bubble-body { background: #63b3ed; }
.xt-footer { color: #555577; }

/* 午夜城执行官专属协议 */
.xt-root {
    --xt-bg: #09060f; /* 极夜黑 */
    --xt-text: #e2d8ee; /* 苍白月光 */
    --xt-text-sub: #7a6b8c;
    --xt-text-muted: #4a3b5c;
    --xt-accent: #8a2be2; /* 核心紫 */
    --xt-accent-bg: rgba(138,43,226,0.15);
    --xt-border: #2d1b4e;
    --xt-radius: 12px; /* 稍微危险一点的锐利边缘 */
    --xt-font: "Kaiti", "STKaiti", serif;
}
.xt-avatar { border-color: var(--xt-accent); box-shadow: 0 0 10px rgba(138,43,226,0.3); }
.xt-section-body { border-left-width: 4px; font-size: 17px; }
.xt-grid-stat { background: rgba(138,43,226,0.05); }
.xt-bar-fill { background: linear-gradient(to right, #2d1b4e, #8a2be2); }
.xt-bubble-right .xt-bubble-body { background: #4a2377; color: #f0e6fa; }
.xt-footer { color: #4a3b5c; }

